import { Test, TestingModule } from '@nestjs/testing';
import { ConflictException } from '@nestjs/common';
import { TenantsService } from '../../src/modules/tenants/tenants.service';
import { PrismaService } from '../../src/infrastructure/database/prisma.service';

const mockPrisma = {
  tenant: {
    findUnique: jest.fn(),
    update: jest.fn(),
  },
  tier: {
    findUnique: jest.fn(),
  },
  agent: {
    findMany: jest.fn(),
  },
  department: {
    findMany: jest.fn(),
  },
  tierAgentPool: {
    findMany: jest.fn(),
  },
  tierDepartmentPool: {
    findMany: jest.fn(),
  },
};

describe('TenantsService', () => {
  let service: TenantsService;

  beforeEach(async () => {
    jest.clearAllMocks();

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        TenantsService,
        { provide: PrismaService, useValue: mockPrisma },
      ],
    }).compile();

    service = module.get(TenantsService);
  });

  it('builds a blocking tier-change preview with required provisioning and policy drift details', async () => {
    mockPrisma.tenant.findUnique.mockResolvedValue({
      id: 'tenant-1',
      name: 'Tenant One',
      slug: 'tenant-one',
      tier: {
        id: 'tier-starter',
        name: 'Starter',
        slug: 'starter',
        maxAgents: 5,
      },
    });

    mockPrisma.tier.findUnique.mockResolvedValue({
      id: 'tier-growth',
      name: 'Growth',
      slug: 'growth',
      maxAgents: 3,
    });

    mockPrisma.agent.findMany.mockResolvedValue([
      {
        id: 'agent-1',
        name: 'Core Agent',
        templateId: 'tmpl-core',
        tierAgentPoolId: 'pool-old',
        deployedFromTierId: null,
      },
      {
        id: 'agent-2',
        name: 'Legacy Agent',
        templateId: 'tmpl-legacy',
        tierAgentPoolId: null,
        deployedFromTierId: 'tier-starter',
      },
      {
        id: 'agent-3',
        name: 'Manual Agent',
        templateId: null,
        tierAgentPoolId: null,
        deployedFromTierId: null,
      },
      {
        id: 'agent-4',
        name: 'Another Agent',
        templateId: 'tmpl-core',
        tierAgentPoolId: null,
        deployedFromTierId: null,
      },
    ]);

    mockPrisma.department.findMany.mockResolvedValue([
      {
        id: 'dept-1',
        name: 'Legacy Department',
        templateId: 'dept-legacy',
        tierDepartmentPoolId: 'dept-pool-old',
        deployedFromTierId: null,
      },
    ]);

    mockPrisma.tierAgentPool.findMany.mockResolvedValue([
      {
        templateId: 'tmpl-core',
        slotType: 'FIXED',
        template: { name: 'Core Agent' },
      },
      {
        templateId: 'tmpl-growth-required',
        slotType: 'FIXED',
        template: { name: 'Growth Required Agent' },
      },
    ]);

    mockPrisma.tierDepartmentPool.findMany.mockResolvedValue([
      {
        departmentTemplateId: 'dept-growth-required',
        slotType: 'FIXED',
        departmentTemplate: { name: 'Growth Required Department' },
      },
    ]);

    const preview = await service.previewTierChange('tenant-1', 'tier-growth');

    expect(preview.compatibility.canChange).toBe(false);
    expect(preview.compatibility.blockingReasons).toEqual([
      'Tenant has 4 selected agents but target tier allows only 3',
    ]);
    expect(preview.impact.agentsToProvision).toEqual([
      {
        templateId: 'tmpl-growth-required',
        templateName: 'Growth Required Agent',
        slotType: 'FIXED',
      },
    ]);
    expect(preview.impact.departmentsToProvision).toEqual([
      {
        templateId: 'dept-growth-required',
        templateName: 'Growth Required Department',
        slotType: 'FIXED',
      },
    ]);
    expect(preview.impact.tierLinkedAgentsOutsideTargetPolicy).toEqual([
      {
        id: 'agent-2',
        name: 'Legacy Agent',
        templateId: 'tmpl-legacy',
      },
    ]);
    expect(preview.impact.tierLinkedDepartmentsOutsideTargetPolicy).toEqual([
      {
        id: 'dept-1',
        name: 'Legacy Department',
        templateId: 'dept-legacy',
      },
    ]);
  });

  it('changes tier when the preview is compatible', async () => {
    mockPrisma.tenant.findUnique.mockResolvedValue({
      id: 'tenant-1',
      name: 'Tenant One',
      slug: 'tenant-one',
      tierId: 'tier-starter',
      tier: {
        id: 'tier-starter',
        name: 'Starter',
        slug: 'starter',
        maxAgents: 5,
      },
    });

    mockPrisma.tier.findUnique.mockResolvedValue({
      id: 'tier-growth',
      name: 'Growth',
      slug: 'growth',
      maxAgents: 10,
    });

    mockPrisma.agent.findMany.mockResolvedValue([
      {
        id: 'agent-1',
        name: 'Core Agent',
        templateId: 'tmpl-core',
        tierAgentPoolId: 'pool-old',
        deployedFromTierId: null,
      },
    ]);
    mockPrisma.department.findMany.mockResolvedValue([]);
    mockPrisma.tierAgentPool.findMany.mockResolvedValue([
      {
        templateId: 'tmpl-core',
        slotType: 'FIXED',
        template: { name: 'Core Agent' },
      },
    ]);
    mockPrisma.tierDepartmentPool.findMany.mockResolvedValue([]);
    mockPrisma.tenant.update.mockResolvedValue({
      id: 'tenant-1',
      tierId: 'tier-growth',
      tier: {
        id: 'tier-growth',
        name: 'Growth',
        slug: 'growth',
        maxAgents: 10,
      },
    });

    const result = await service.changeTier('tenant-1', 'tier-growth');

    expect(mockPrisma.tenant.update).toHaveBeenCalledWith({
      where: { id: 'tenant-1' },
      data: { tierId: 'tier-growth' },
      include: { tier: true },
    });
    expect(result.tierId).toBe('tier-growth');
  });

  it('rejects tier changes when the preview is incompatible', async () => {
    mockPrisma.tenant.findUnique.mockResolvedValue({
      id: 'tenant-1',
      name: 'Tenant One',
      slug: 'tenant-one',
      tier: {
        id: 'tier-starter',
        name: 'Starter',
        slug: 'starter',
        maxAgents: 5,
      },
    });

    mockPrisma.tier.findUnique.mockResolvedValue({
      id: 'tier-growth',
      name: 'Growth',
      slug: 'growth',
      maxAgents: 0,
    });

    mockPrisma.agent.findMany.mockResolvedValue([
      {
        id: 'agent-1',
        name: 'Only Agent',
        templateId: 'tmpl-core',
        tierAgentPoolId: null,
        deployedFromTierId: null,
      },
    ]);
    mockPrisma.department.findMany.mockResolvedValue([]);
    mockPrisma.tierAgentPool.findMany.mockResolvedValue([]);
    mockPrisma.tierDepartmentPool.findMany.mockResolvedValue([]);

    await expect(service.changeTier('tenant-1', 'tier-growth')).rejects.toThrow(
      ConflictException,
    );
    expect(mockPrisma.tenant.update).not.toHaveBeenCalled();
  });
});